 @Test void deferAndPriorityKeepQuantitiesAndAcknowledgements(){
  Long line=line();var change=new LinkedHashMap<String,Object>(Map.of("storeId",f.store,"lineId",line,"lineKind","LOT_LINE","requestKey",key(),"expectedRevision","0","state","DEFERRED","reason","Contrôle de la date","priority",80,"instruction","Vérifier la date"));
  call(f.picker,"PUT","/orders/"+f.order+"/lines",change).then().statusCode(403);
  var first=call(f.manager,"PUT","/orders/"+f.order+"/lines",change).then().statusCode(200).extract();Long directive=first.jsonPath().getLong("id");String revision=first.path("revision");
  call(f.manager,"PUT","/orders/"+f.order+"/lines",change).then().statusCode(200);
  call(f.picker,"POST","/orders/"+f.order+"/lines/"+directive+"/ack?storeId="+f.store+"&version=1",null).then().statusCode(200);
  change.put("requestKey",key());change.put("expectedRevision",revision);change.put("priority",90);change.put("state","READY");var next=call(f.manager,"PUT","/orders/"+f.order+"/lines",change).then().statusCode(200).extract();
  assertEquals(1,next.jsonPath().getLong("instructionVersion"));
  call(f.picker,"GET","/orders/"+f.order+"/lines?storeId="+f.store,null).then().statusCode(200).body("[0].acknowledged",org.hamcrest.Matchers.is(true));
  QuarkusTransaction.requiringNew().run(()->assertEquals(new BigDecimal("2.000"),PickedItem.<PickedItem>findById(f.item).quantity));
  change.put("requestKey",key());change.put("expectedRevision",next.<String>path("revision"));change.put("instruction","Nouvelle consigne");call(f.manager,"PUT","/orders/"+f.order+"/lines",change).then().statusCode(200);
  call(f.picker,"POST","/orders/"+f.order+"/lines/"+directive+"/ack?storeId="+f.store+"&version=1",null).then().statusCode(409);
 }
